import type { PageProps, Row } from '../kit';
import { Badge, Band, DataTable, DateText, Pairs, RefName } from '../kit';

export default function FnSfr03103Page({ role }: PageProps) {
  // 이 기능에는 조회 API가 없어 화면에서 읽어 올 목록이 없다.
  const rows: Row[] = [];
  return (
    <div className="bento">
      <section className="box span-12">
        <h2>보관 문서</h2>
        <Band total={rows.length} />
        <DataTable
          columns={[
            { key: 'documentNumber', label: '문서번호' },
            { key: 'title', label: '제목' },
            {
              key: 'drafterId',
              label: '담당자',
              render: (row) => (
                <RefName table="employee" role={role} value={row.drafterId} />
              ),
            },
            {
              key: 'approvalStatus',
              label: '결재 진행 상태',
              render: (row) => <Badge value={row.approvalStatus} />,
            },
            {
              key: 'completedAt',
              label: '완료 일시',
              render: (row) => <DateText value={row.completedAt} time />,
            },
          ]}
          rows={rows}
          empty="표시할 보관 문서가 없습니다."
        />
      </section>
      <section className="box span-12">
        <h2>보관 처리</h2>
        <Pairs
          items={[
            ['처리 시점', '결재 진행 상태가 완료로 바뀔 때'],
            ['처리 방식', '시스템이 자동으로 지정 문서함 이관, PDF 변환, ECM 저장을 수행합니다.'],
            ['사용자 처리', '이 화면에서 직접 처리하는 버튼은 없습니다.'],
          ]}
        />
      </section>
    </div>
  );
}
